import { useCallback, useEffect, useState } from 'react'

import type { ExpenseViewModel, FieldErrors, NewExpense } from '../../application/ExpenseViewModel'
import { useExpensesUseCases } from '../useExpensesUseCases/useExpensesUseCases'

export const useExpenses = () => {
  const { listExpenses, submitExpense } = useExpensesUseCases()
  const [expenses, setExpenses] = useState<ExpenseViewModel[]>([])
  const [loading, setLoading] = useState(true)
  const [loadError, setLoadError] = useState<string | null>(null)
  const [fieldErrors, setFieldErrors] = useState<FieldErrors>({})
  const [submitError, setSubmitError] = useState<string | null>(null)
  const [submitting, setSubmitting] = useState(false)

  useEffect(() => {
    let active = true
    listExpenses
      .execute()
      .then((items) => active && setExpenses(items))
      .catch((error: Error) => active && setLoadError(error.message))
      .finally(() => active && setLoading(false))
    return () => {
      active = false
    }
  }, [listExpenses])

  const submit = useCallback(
    async (expense: NewExpense): Promise<boolean> => {
      setSubmitting(true)
      setSubmitError(null)
      try {
        const result = await submitExpense.execute(expense)
        if (!result.accepted) {
          setFieldErrors(result.errors)
          return false
        }
        setFieldErrors({})
        setExpenses(await listExpenses.execute())
        return true
      } catch (error) {
        setSubmitError(error instanceof Error ? error.message : 'Something went wrong')
        return false
      } finally {
        setSubmitting(false)
      }
    },
    [listExpenses, submitExpense],
  )

  return { expenses, loading, loadError, fieldErrors, submitError, submitting, submit }
}
