import { ExpenseForm } from '../ExpenseForm/ExpenseForm'
import { ExpenseList } from '../ExpenseList/ExpenseList'
import { useExpenses } from '../useExpenses/useExpenses'

export const ExpensesPage = () => {
  const { expenses, loading, loadError, fieldErrors, submitError, submitting, submit } = useExpenses()

  return (
    <main>
      <h1>My expenses</h1>
      {loading && <p>Loading…</p>}
      {loadError && <p role="alert">{loadError}</p>}
      {!loading && !loadError && <ExpenseList expenses={expenses} />}
      <h2>New expense</h2>
      <ExpenseForm errors={fieldErrors} submitting={submitting} onSubmit={submit} />
      {submitError && <p role="alert">{submitError}</p>}
    </main>
  )
}
