import { useMemo } from 'react'

import { ListExpenses } from '../../expenses/application/ListExpenses'
import { SubmitExpense } from '../../expenses/application/SubmitExpense'
import { HttpExpenseGateway } from '../../expenses/infrastructure/HttpExpenseGateway'
import { ExpensesPage } from '../../expenses/ui/ExpensesPage/ExpensesPage'
import { ExpensesUseCasesContext } from '../../expenses/ui/useExpensesUseCases/useExpensesUseCases'

